sigset_t wait_for;
size_t set_size;
int ret;

// Assuming wait_for is initialized (signals to unblock)
// Example: sigemptyset(&wait_for); sigaddset(&wait_for, SIGTERM);

set_size = sizeof(sigset_t);

// Atomically changes signal mask to wait_for and sleeps.
// Returns -1 upon interrupt (EINTR) or error (EFAULT).
ret = rt_sigsuspend(&wait_for, set_size);

if (ret == -1) {
    // E.g., errno == EINTR (signal caught)
    // or errno == EFAULT (invalid mask pointer)
}
